mapper.insert:
MERGE INTO MST_BOND_CREDIT_RATING a USING (
SELECT #{item.oCode} O_CODE, #{item.gradeOrgId} GRADE_ORG_ID, #{item.gradeDate} GRADE_DATE, #{item.oType} O_TYPE, #{item.shortLongTerm} SHORT_LONG_TERM, #{item.gradeResult} GRADE_RESULT, #{item.dataSource} DATA_SOURCE, #{item.source} SOURCE, #{item.status} STATUS, #{item.errMsg} ERR_MSG, #{item.createUser} CREATE_USER, #{item.createDept} CREATE_DEPT, #{item.createTime} CREATE_TIME, #{item.updateUser} UPDATE_USER, #{item.updateTime} UPDATE_TIME FROM DUAL
) b ON (a.O_CODE = b.O_CODE AND a.GRADE_ORG_ID = b.GRADE_ORG_ID AND a.GRADE_DATE = b.GRADE_DATE AND a.O_TYPE = b.O_TYPE) WHEN MATCHED THEN UPDATE SET a.SHORT_LONG_TERM = b.SHORT_LONG_TERM, a.GRADE_RESULT = b.GRADE_RESULT, a.SOURCE = b.SOURCE, a.STATUS = b.STATUS, a.ERR_MSG = b.ERR_MSG, a.UPDATE_USER = b.UPDATE_USER, a.UPDATE_TIME = b.UPDATE_TIME WHEN NOT MATCHED THEN INSERT ( O_CODE,GRADE_ORG_ID, GRADE_DATE,O_TYPE,SHORT_LONG_TERM,GRADE_RESULT,DATA_SOURCE,SOURCE,STATUS,ERR_MSG, CREATE_USER,CREATE_DEPT,CREATE_TIME,UPDATE_USER,UPDATE_TIME) VALUES (b.O_CODE,b.GRADE_ORG_ID,b.GRADE_DATE,b.O_TYPE,b.SHORT_LONG_TERM,b.GRADE_RESULT,b.DATA_SOURCE,b.SOURCE,b.STATUS,b.ERR_MSG, b.CREATE_USER,b.CREATE_DEPT,b.CREATE_TIME,b.UPDATE_USER,b.UPDATE_TIME)

mapper.update:
update MST_BOND_CREDIT_RATING



        SHORT_LONG_TERM = #{shortLongTerm},


        GRADE_RESULT = #{gradeResult},


        STATUS = #{status},


        UPDATE_USER = #{updateUser},


        UPDATE_TIME = #{updateTime}




        O_CODE = #{oCode}


        AND GRADE_ORG_ID = #{gradeOrgId}


        AND GRADE_DATE = #{gradeDate}


        AND O_TYPE = #{oType}

mapper.select:
select  from MST_BOND_CREDIT_RATING


        O_CODE = #{oCode}


        and GRADE_ORG_ID = #{gradeOrgId}


        and GRADE_DATE = #{gradeDate}


        and O_TYPE = #{oType}

select ,b.ASSET_NAME oName from MST_BOND_CREDIT_RATING a

    left join  (SELECT DISTINCT ASSET_CODE,ASSET_NAME FROM CHB_ASSET_INFO) b on a.O_CODE = b.ASSET_CODE


        O_TYPE = #{oType}



            #{item}




        and SHORT_LONG_TERM = #{shortLongTerm}


        and STATUS = #{status}


        and GRADE_DATE >= to_date(#{gradeDateStart},'yyyy-mm-dd')


        and GRADE_DATE <= to_date(#{gradeDateEnd},'yyyy-mm-dd')
